					</d:eq>
				</d:or>
				${supportsUploadTime ? `
						<d:or>
							<d:gt>
								<d:prop>
									<d:getlastmodified/>
								</d:prop>
								<d:literal>${timestamp}</d:literal>
							</d:gt>
							<d:gt>
								<d:prop>
									<nc:upload_time/>
								</d:prop>
								<d:literal>${timestamp}</d:literal>
							</d:gt>
						</d:or>
				` : `
					<d:gt>
						<d:prop>
							<d:getlastmodified/>
						</d:prop>
						<d:literal>${timestamp}</d:literal>
